import { useCallback } from 'react';
import { useIntl } from 'react-intl';

import { _useDateTimeMessages } from '../../forms-core/hooks/useDateTimeMessages.js';
import {
  _getFormattedMinMax,
  _getFormattedTimeValue,
} from '../../forms-core/time/timeParser.js';
import type { DateTimeRangeError, DateTimeRangePickerProps } from '../types.js';

export const useDateTimeRangeErrorMessage = ({
  min,
  max,
  precision,
}: Pick<DateTimeRangePickerProps, 'max' | 'min' | 'precision'>) => {
  const intl = useIntl();
  const { formatString } = _useDateTimeMessages({ precision });
  const getErrorMessage = useCallback(
    (error: DateTimeRangeError, source: 'from' | 'to' | 'both') => {
      const expectedFormat = formatString;

      if (error === 'invalid') {
        if (source === 'from') {
          return intl.formatMessage(
            {
              defaultMessage:
                'Invalid start time. Expected format: {expectedFormat} or -2h',
              id: 'gUytGV2/z5ih0rqh',
              description: 'Given from value is invalid',
            },
            {
              expectedFormat,
            },
          );
        }

        if (source === 'to') {
          return intl.formatMessage(
            {
              defaultMessage:
                'Invalid end time. Expected format: {expectedFormat} or -2h',
              id: 'IpEUGogA+qstYTQH',
              description: 'Given to value is invalid',
            },
            {
              expectedFormat,
            },
          );
        }

        return intl.formatMessage(
          {
            defaultMessage:
              'Invalid start and end time. Expected format: {expectedFormat} or -2h',
            id: '4PM5rUSi11eRU4sn',
            description: 'Given from and to values are expectedFormat',
          },
          {
            expectedFormat,
          },
        );
      }

      if (error === 'invalidOrder') {
        return intl.formatMessage({
          defaultMessage: 'Start time must be before end time.',
          id: '6mmv2U9zlsEKmabI',
          description: 'Given from must be before given end time',
        });
      }

      if (error === 'outsideRange') {
        const { min: from, max: to } = _getFormattedMinMax(min, max, precision);

        if (min && max) {
          return intl.formatMessage(
            {
              defaultMessage: 'Only dates between {from} → {to} are available.',
              id: 't2jnKY+cKh0VjSHT',
              description: 'Given date are not within the valid range.',
            },
            {
              from,
              to,
            },
          );
        }

        if (min) {
          return intl.formatMessage(
            {
              defaultMessage: 'Only dates after {from} are available.',
              id: 'QXOCOrq5Seu+1A93',
              description: 'Given dates are not within the valid range.',
            },
            {
              from,
            },
          );
        }

        if (max) {
          return intl.formatMessage(
            {
              defaultMessage: 'Only dates before {to} are available.',
              id: 'LCOdjIuMh7fDcI1v',
              description: 'Given dates are is not within the valid range.',
            },
            {
              to: _getFormattedTimeValue({
                absoluteDate: max,
                type: 'iso8601',
                value: max,
              }),
            },
          );
        }

        return intl.formatMessage({
          defaultMessage: 'Selected time is outside of the valid range.',
          id: 'r2DiyNP5gUAg0s5f',
          description: 'Given dates are not within the valid range.',
        });
      }

      if (error === 'valueMissing') {
        if (source === 'from') {
          return intl.formatMessage({
            defaultMessage: 'Please enter a start time.',
            id: 'GUeetpTpusqFkMi+',
            description: 'From value is missing.',
          });
        }

        if (source === 'to') {
          return intl.formatMessage({
            defaultMessage: 'Please enter an end time.',
            id: 'tfHTZkRc7sr/Ypcl',
            description: 'End value is missing.',
          });
        }

        return intl.formatMessage({
          defaultMessage: 'Please enter a start and end time.',
          id: 'gKh7cp2la6bFgMqZ',
          description: 'Start and end value are missing.',
        });
      }
    },
    [formatString, intl, max, min, precision],
  );

  return { getErrorMessage };
};
